// Plutto — web notifications (generated by scripts/build-web.mjs).
const ICON = '/m/icons/icon-192.png';
const APP = '/app';
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (e) => e.waitUntil(self.clients.claim()));
self.addEventListener('push', (e) => {
  let m = {};
  try { m = e.data ? e.data.json() : {}; } catch (_) { m = { body: e.data ? e.data.text() : '' }; }
  e.waitUntil(self.registration.showNotification(m.title || 'Plutto', {
    body: m.body || '', icon: ICON, badge: ICON, tag: 'plutto', data: m.data || {},
  }));
});
// A tap opens the app on what the notification is about — the same data payload
// the phone routes (a feature, a tab, the paywall, a url). An open app is focused
// and told; otherwise the app is opened with it in ?notif=.
self.addEventListener('notificationclick', (e) => {
  e.notification.close();
  const data = e.notification.data || {};
  e.waitUntil((async () => {
    const wins = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    const app = wins.find((c) => { const p = new URL(c.url).pathname; return p.startsWith(APP) || p.startsWith('/m/'); });
    if (app) { await app.focus(); app.postMessage({ type: 'plutto-notification', data }); return; }
    await self.clients.openWindow(APP + '?notif=' + encodeURIComponent(JSON.stringify(data)));
  })());
});
